//! **Synthetic fixtures, written here, in memory.**
//!
//! Every PDF the tests read is generated by this module at test time: a
//! rendered-text page, two pages, a password-protected file, one encrypted
//! with permissions only, a damaged file, a scan, a page in a font that maps
//! nothing, and an HTML page. Nothing is downloaded, so no fixture's licence
//! is a question, and nothing is checked in as a binary: a PDF's
//! cross-reference table is byte offsets, which a checkout that rewrote line
//! endings would silently break, and AGENTS.md commits a binary only when
//! nothing can produce it. Tests touch no disk; these bytes go straight to
//! the code under test.
//!
//! The encryption is the PDF standard security handler, revision 2 (40-bit
//! RC4, ISO 32000-1 §7.6.3, algorithms 2, 3 and 4), written out here because
//! no PDF writer is in the tree. `md5` is already a workspace dependency.

/// An HTML page with everything the stripper must drop: a doctype, a style,
/// a script, a comment, attributes, entities and a table.
pub const HTML: &str = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n\
<meta charset=\"utf-8\">\n<title>Quarterly report</title>\n\
<style>.hidden { color: red; }</style>\n\
<script>var notvisible = \"scriptword\";</script>\n</head>\n<body>\n\
<h1 class=\"title\">Harbour&nbsp;lights</h1>\n\
<p>The <b>quick</b> brown\nfox<br>jumps over &amp; under &#x2014; caf&eacute;.</p>\n\
<!-- commentword -->\n\
<table><tr><td>cell one</td><td>cell two</td></tr></table>\n\
<a href=\"https://example.invalid/hrefword\" title='attrword'>link text</a>\n\
</body>\n</html>\n";

/// **Files from memory**, for the job and the service: a path names bytes,
/// and nothing touches a disk.
#[derive(Default)]
pub struct Memory(std::collections::HashMap<std::path::PathBuf, Vec<u8>>);

impl Memory {
    pub fn with(mut self, path: &str, bytes: impl Into<Vec<u8>>) -> Memory {
        self.0.insert(path.into(), bytes.into());
        self
    }
}

impl crate::job::Files for Memory {
    fn open(&self, path: &std::path::Path) -> std::io::Result<Box<dyn std::io::Read + Send>> {
        match self.0.get(path) {
            Some(bytes) => Ok(Box::new(std::io::Cursor::new(bytes.clone()))),
            None => Err(std::io::ErrorKind::NotFound.into()),
        }
    }
}

/// One page of a [`Scripted`] document.
pub enum Script {
    Words(&'static str),
    /// Blocks until the test lets it go, then has words nobody waits for.
    Stuck(std::sync::Mutex<Option<std::sync::mpsc::Receiver<()>>>),
    Panics,
}

/// **A document whose pages misbehave on cue**: one that never finishes, one
/// that panics — what a hostile PDF does to the parser, without needing one.
pub struct Scripted(pub Vec<Script>);

impl crate::pdf::Document for Scripted {
    fn page_count(&self) -> u32 {
        self.0.len() as u32
    }

    fn read_pages(
        &self,
        from: u32,
        to: u32,
        out: &mut dyn FnMut(u32, crate::accept::Layer) -> bool,
    ) {
        for number in from..=to {
            let text = match &self.0[number as usize - 1] {
                Script::Words(text) => *text,
                Script::Stuck(release) => {
                    let wait = release.lock().unwrap().take();
                    if let Some(wait) = wait {
                        let _ = wait.recv();
                    }
                    "late words nobody waits for"
                }
                Script::Panics => panic!("a page the parser could not survive"),
            };
            let layer = crate::accept::Layer {
                text: text.into(),
                chars: text.chars().filter(|c| !c.is_whitespace()).count(),
                unmapped: 0,
                picture_share: 0.0,
            };
            if !out(number, layer) {
                return;
            }
        }
    }
}

/// A page that blocks until the returned sender is dropped or sent to.
pub fn stuck() -> (std::sync::mpsc::Sender<()>, Script) {
    let (release, wait) = std::sync::mpsc::channel();
    (release, Script::Stuck(std::sync::Mutex::new(Some(wait))))
}

/// An engine whose every PDF is `pages`, found at `path`.
pub fn scripted_engine(
    pages: Vec<Script>,
    path: &str,
    page_budget: std::time::Duration,
    abandoned: std::sync::Arc<crate::budget::Abandoned>,
) -> crate::job::Engine {
    let document: std::sync::Arc<dyn crate::pdf::Document> = std::sync::Arc::new(Scripted(pages));
    crate::job::Engine {
        files: std::sync::Arc::new(Memory::default().with(path, one_page())),
        open_pdf: std::sync::Arc::new(move |_| Ok(std::sync::Arc::clone(&document))),
        page_budget,
        load_budget: std::time::Duration::from_secs(30),
        abandoned,
    }
}

/// What [`HTML`] reads as.
pub const HTML_TEXT: &str = "Quarterly report\nHarbour lights\nThe quick brown fox\n\
jumps over & under — café.\ncell one cell two\nlink text";

const PAD: [u8; 32] = [
    0x28, 0xBF, 0x4E, 0x5E, 0x4E, 0x75, 0x8A, 0x41, 0x64, 0x00, 0x4E, 0x56, 0xFF, 0xFA, 0x01, 0x08,
    0x2E, 0x2E, 0x00, 0xB6, 0xD0, 0x68, 0x3E, 0x80, 0x2F, 0x0C, 0xA9, 0xFE, 0x64, 0x53, 0x69, 0x7A,
];

fn padded(password: &str) -> Vec<u8> {
    let mut out: Vec<u8> = password.bytes().take(32).collect();
    let fill = 32 - out.len();
    out.extend_from_slice(&PAD[..fill]);
    out
}

fn rc4(key: &[u8], data: &[u8]) -> Vec<u8> {
    let mut s: [u8; 256] = std::array::from_fn(|i| i as u8);
    let mut j: u8 = 0;
    for i in 0..256 {
        j = j.wrapping_add(s[i]).wrapping_add(key[i % key.len()]);
        s.swap(i, usize::from(j));
    }
    let (mut i, mut j) = (0u8, 0u8);
    data.iter()
        .map(|byte| {
            i = i.wrapping_add(1);
            j = j.wrapping_add(s[usize::from(i)]);
            s.swap(usize::from(i), usize::from(j));
            byte ^ s[usize::from(s[usize::from(i)].wrapping_add(s[usize::from(j)]))]
        })
        .collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02X}")).collect()
}

struct Security {
    key: Vec<u8>,
    owner: Vec<u8>,
    user: Vec<u8>,
    permissions: i32,
    id: Vec<u8>,
}

impl Security {
    fn new(user: &str, owner: &str) -> Security {
        let permissions: i32 = -4;
        let id: Vec<u8> = (0u8..16)
            .map(|i| i.wrapping_mul(37).wrapping_add(11))
            .collect();
        // Algorithm 3: the owner entry.
        let owner_key = &md5::compute(padded(owner)).0[..5];
        let owner_entry = rc4(owner_key, &padded(user));
        // Algorithm 2: the file key.
        let mut input = padded(user);
        input.extend_from_slice(&owner_entry);
        input.extend_from_slice(&permissions.to_le_bytes());
        input.extend_from_slice(&id);
        let key = md5::compute(&input).0[..5].to_vec();
        // Algorithm 4: the user entry.
        let user_entry = rc4(&key, &PAD);
        Security {
            key,
            owner: owner_entry,
            user: user_entry,
            permissions,
            id,
        }
    }

    /// Algorithm 1: the key for one object, generation 0.
    fn object_key(&self, number: u32) -> Vec<u8> {
        let mut input = self.key.clone();
        input.extend_from_slice(&number.to_le_bytes()[..3]);
        input.extend_from_slice(&[0, 0]);
        md5::compute(&input).0[..10].to_vec()
    }
}

/// A PDF, one object at a time.
pub struct Writer {
    objects: Vec<Vec<u8>>,
    security: Option<Security>,
}

impl Writer {
    pub fn new() -> Writer {
        Writer {
            objects: Vec::new(),
            security: None,
        }
    }

    /// A file encrypted with the standard handler. An empty `user` password
    /// opens it without asking — permissions only.
    pub fn encrypted(user: &str, owner: &str) -> Writer {
        Writer {
            objects: Vec::new(),
            security: Some(Security::new(user, owner)),
        }
    }

    /// The number the next object will have.
    pub fn next(&self) -> u32 {
        self.objects.len() as u32 + 1
    }

    /// Add an object whose body holds no strings (strings would have to be
    /// encrypted too, and no fixture needs one).
    pub fn add(&mut self, body: &str) -> u32 {
        self.objects.push(body.as_bytes().to_vec());
        self.objects.len() as u32
    }

    /// Add a stream, encrypted when the file is.
    pub fn stream(&mut self, dict: &str, data: &[u8]) -> u32 {
        let number = self.next();
        let data = match &self.security {
            Some(security) => rc4(&security.object_key(number), data),
            None => data.to_vec(),
        };
        let mut body = format!("<< {dict} /Length {} >>\nstream\n", data.len()).into_bytes();
        body.extend_from_slice(&data);
        body.extend_from_slice(b"\nendstream");
        self.objects.push(body);
        number
    }

    /// The file, with `catalog` as its root.
    pub fn finish(mut self, catalog: u32) -> Vec<u8> {
        let encrypt = self.security.as_ref().map(|security| {
            format!(
                "<< /Filter /Standard /V 1 /R 2 /Length 40 /O <{}> /U <{}> /P {} >>",
                hex(&security.owner),
                hex(&security.user),
                security.permissions
            )
        });
        let encrypt = encrypt.map(|body| self.add(&body));
        let mut out = b"%PDF-1.4\n%\xE2\xE3\xCF\xD3\n".to_vec();
        let mut offsets = Vec::new();
        for (index, body) in self.objects.iter().enumerate() {
            offsets.push(out.len());
            out.extend_from_slice(format!("{} 0 obj\n", index + 1).as_bytes());
            out.extend_from_slice(body);
            out.extend_from_slice(b"\nendobj\n");
        }
        let xref = out.len();
        out.extend_from_slice(format!("xref\n0 {}\n", offsets.len() + 1).as_bytes());
        out.extend_from_slice(b"0000000000 65535 f \n");
        for offset in offsets {
            out.extend_from_slice(format!("{offset:010} 00000 n \n").as_bytes());
        }
        let mut trailer = format!("<< /Size {} /Root {catalog} 0 R", self.objects.len() + 1);
        if let (Some(number), Some(security)) = (encrypt, &self.security) {
            let id = hex(&security.id);
            trailer.push_str(&format!(" /Encrypt {number} 0 R /ID [<{id}> <{id}>]"));
        }
        trailer.push_str(" >>");
        out.extend_from_slice(format!("trailer\n{trailer}\nstartxref\n{xref}\n%%EOF\n").as_bytes());
        out
    }
}

/// A literal string for a content stream.
fn literal(text: &str) -> String {
    let mut out = String::from("(");
    for c in text.chars() {
        if matches!(c, '(' | ')' | '\\') {
            out.push('\\');
        }
        out.push(c);
    }
    out.push(')');
    out
}

/// Content that sets `lines` in 12-point Helvetica, one under the other.
pub fn lines(lines: &[&str]) -> String {
    let mut out = String::from("BT /F1 12 Tf 72 720 Td\n");
    for (index, line) in lines.iter().enumerate() {
        if index > 0 {
            out.push_str("0 -16 Td\n");
        }
        out.push_str(&format!("{} Tj\n", literal(line)));
    }
    out.push_str("ET\n");
    out
}

/// A document of US-letter pages, one per content stream, with Helvetica as
/// `/F1` (a standard font, not embedded — the common case) and, where a page
/// draws one, a small grey picture as `/Im1`.
pub fn document(writer: &mut Writer, pages: &[String]) -> u32 {
    let font = writer
        .add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
    let picture = writer.stream(
        "/Type /XObject /Subtype /Image /Width 2 /Height 2 /ColorSpace /DeviceGray /BitsPerComponent 8",
        &[0x00, 0xFF, 0xFF, 0x00],
    );
    let tree = writer.next() + pages.len() as u32 * 2;
    let mut kids = Vec::new();
    for content in pages {
        let stream = writer.stream("", content.as_bytes());
        let page = writer.add(&format!(
            "<< /Type /Page /Parent {tree} 0 R /MediaBox [0 0 612 792] /Contents {stream} 0 R \
             /Resources << /Font << /F1 {font} 0 R >> /XObject << /Im1 {picture} 0 R >> >> >>"
        ));
        kids.push(format!("{page} 0 R"));
    }
    let made = writer.add(&format!(
        "<< /Type /Pages /Kids [{}] /Count {} >>",
        kids.join(" "),
        pages.len()
    ));
    assert_eq!(
        made, tree,
        "the page tree must be the object the pages name"
    );
    writer.add(&format!("<< /Type /Catalog /Pages {tree} 0 R >>"))
}

fn plain(pages: &[String]) -> Vec<u8> {
    let mut writer = Writer::new();
    let catalog = document(&mut writer, pages);
    writer.finish(catalog)
}

/// **Rendered text**: one page, with a word whose letters are kerned apart
/// and two words set apart by position rather than by a space.
pub fn one_page() -> Vec<u8> {
    let mut content = lines(&["Koru reads the words in a PDF", "quartz zephyr jukebox"]);
    content = content.replace("ET\n", "0 -16 Td\n[(Harb) 20 (our) -350 (lights)] TJ\nET\n");
    plain(&[content])
}

/// What [`one_page`] reads as.
pub const ONE_PAGE_TEXT: &str =
    "Koru reads the words in a PDF\nquartz zephyr jukebox\nHarbour lights";

/// **Two pages**, each with its own words.
pub fn two_pages() -> Vec<u8> {
    plain(&[
        lines(&["alpha bravo charlie"]),
        lines(&["delta echo foxtrot"]),
    ])
}

/// `n` pages, page `k` reading "page number k".
pub fn many_pages(n: u32) -> Vec<u8> {
    let pages: Vec<String> = (1..=n)
        .map(|k| lines(&[&format!("page number {k}")]))
        .collect();
    plain(&pages)
}

/// Text, then a blank page, then text: a blank page is not a scan.
pub fn with_blank_page() -> Vec<u8> {
    plain(&[
        lines(&["before the blank page"]),
        String::new(),
        lines(&["after the blank page"]),
    ])
}

/// A page of text, then **a scan**: a full-page picture with only a page
/// number in real text.
pub fn text_then_scan() -> Vec<u8> {
    plain(&[
        lines(&["typed words on the first page"]),
        format!(
            "q 612 0 0 792 0 0 cm /Im1 Do Q\n{}",
            lines(&["2"]).replace("72 720 Td", "300 20 Td")
        ),
    ])
}

/// A single scanned page and nothing else.
pub fn scan() -> Vec<u8> {
    plain(&["q 612 0 0 792 0 0 cm /Im1 Do Q\n".to_string()])
}

/// **A font that maps nothing**: a Type3 font whose glyph names are in no
/// glyph list and that has no `ToUnicode`, so every glyph is unmapped.
pub fn unmapped() -> Vec<u8> {
    let mut writer = Writer::new();
    let glyph = writer.stream("", b"600 0 0 0 500 700 d1 0 0 500 700 re f");
    let names = ["/zzglyph"; 12].join(" ");
    let widths = ["600"; 12].join(" ");
    let font = writer.add(&format!(
        "<< /Type /Font /Subtype /Type3 /FontBBox [0 0 1000 1000] /FontMatrix [0.001 0 0 0.001 0 0] \
         /CharProcs << /zzglyph {glyph} 0 R >> /Encoding << /Type /Encoding /Differences [65 {names}] >> \
         /FirstChar 65 /LastChar 76 /Widths [{widths}] /Resources << >> >>"
    ));
    let content = writer.stream("", b"BT /T3 12 Tf 72 700 Td (ABCDEFGHIJKL) Tj ET");
    let tree = writer.next() + 1;
    let page = writer.add(&format!(
        "<< /Type /Page /Parent {tree} 0 R /MediaBox [0 0 612 792] /Contents {content} 0 R \
         /Resources << /Font << /T3 {font} 0 R >> >> >>"
    ));
    let made = writer.add(&format!("<< /Type /Pages /Kids [{page} 0 R] /Count 1 >>"));
    assert_eq!(made, tree);
    let catalog = writer.add(&format!("<< /Type /Catalog /Pages {tree} 0 R >>"));
    writer.finish(catalog)
}

/// A page tree with no pages in it.
pub fn no_pages() -> Vec<u8> {
    plain(&[])
}

/// **Hostile: a page tree that contains itself.**
pub fn page_tree_cycle() -> Vec<u8> {
    let mut writer = Writer::new();
    let content = writer.stream("", lines(&["a page inside a cycle of pages"]).as_bytes());
    let tree = writer.next() + 2;
    let font = writer.add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");
    let page = writer.add(&format!(
        "<< /Type /Page /Parent {tree} 0 R /MediaBox [0 0 612 792] /Contents {content} 0 R \
         /Resources << /Font << /F1 {font} 0 R >> >> >>"
    ));
    let made = writer.add(&format!(
        "<< /Type /Pages /Kids [{page} 0 R {tree} 0 R] /Count 2 >>"
    ));
    assert_eq!(made, tree);
    let catalog = writer.add(&format!("<< /Type /Catalog /Pages {tree} 0 R >>"));
    writer.finish(catalog)
}

/// **Hostile: a form that draws itself**, for ever if nothing stops it.
pub fn form_recursion() -> Vec<u8> {
    let mut writer = Writer::new();
    let form = writer.next();
    let made = writer.stream(
        &format!(
            "/Type /XObject /Subtype /Form /BBox [0 0 612 792] \
             /Resources << /XObject << /Fm1 {form} 0 R >> >>"
        ),
        b"/Fm1 Do",
    );
    assert_eq!(made, form);
    let content = writer.stream(
        "",
        lines(&["words beside a form that draws itself"])
            .replace("ET\n", "ET\n/Fm1 Do\n")
            .as_bytes(),
    );
    let font = writer.add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");
    let tree = writer.next() + 1;
    let page = writer.add(&format!(
        "<< /Type /Page /Parent {tree} 0 R /MediaBox [0 0 612 792] /Contents {content} 0 R \
         /Resources << /Font << /F1 {font} 0 R >> /XObject << /Fm1 {form} 0 R >> >> >>"
    ));
    let made = writer.add(&format!("<< /Type /Pages /Kids [{page} 0 R] /Count 1 >>"));
    assert_eq!(made, tree);
    let catalog = writer.add(&format!("<< /Type /Catalog /Pages {tree} 0 R >>"));
    writer.finish(catalog)
}

/// **Password-protected**: opening it needs the user password `secret`.
pub fn encrypted() -> Vec<u8> {
    let mut writer = Writer::encrypted("secret", "owner-secret");
    let catalog = document(&mut writer, &[lines(&["words behind a password"])]);
    writer.finish(catalog)
}

/// Encrypted **with permissions only**: the user password is empty, so any
/// reader opens it, and it is not password-protected.
pub fn permissions_only() -> Vec<u8> {
    let mut writer = Writer::encrypted("", "owner-secret");
    let catalog = document(&mut writer, &[lines(&["unlocked words appear here"])]);
    writer.finish(catalog)
}

/// **Damaged**: a PDF header, then nothing a parser can recover a document
/// from.
pub fn damaged() -> Vec<u8> {
    let mut out = b"%PDF-1.7\n".to_vec();
    for _ in 0..40 {
        out.extend_from_slice(b"this is not an object, a table or a trailer\n");
    }
    out.extend_from_slice(b"%%EOF\n");
    out
}
